-- Seed: the catalogue as it stands in DevicesScreen.kt on 2026-08-24, plus the
-- three cards approved today (Alpine Silence, TheraSpecs, TheraSpecs FL-Pro).
-- Idempotent: re-running updates the English copy rather than duplicating rows.

on conflict (key) do update set title = excluded.title, blurb = excluded.blurb, sort = excluded.sort, updated_at = now();

on conflict (key) do update set
  group_key = excluded.group_key, name = excluded.name, what = excluded.what,
  evidence = excluded.evidence, pros = excluded.pros, cons = excluded.cons,
  rating = excluded.rating, rating_source = excluded.rating_source, rating_url = excluded.rating_url,
  icon_key = excluded.icon_key, photo_path = excluded.photo_path, access = excluded.access,
  safety_note = excluded.safety_note, sort = excluded.sort, updated_at = now();

on conflict (item_key, slug) do update set
  countries = excluded.countries, url = excluded.url, code = excluded.code,
  note = excluded.note, sort = excluded.sort, updated_at = now();
